rules_tcl does not ship a pre-registered toolchain — you declare the interpreter and libraries you want and register a tcl_toolchain locally. Add the following to your MODULE.bazel: bazel_dep(name = "rules_tcl", version = "{version}")
bazel_dep(name = "tcl_lang", version = "{tcl_lang_version}")
bazel_dep(name = "bazel_skylib", version = "{bazel_skylib_version}") http_archive = use_repo_rule("@bazel_tools//tools/build_defs/repo:http.bzl", "http_archive") http_archive( name = "tcllib", build_file = "@rules_tcl//tcl/private:BUILD.tcllib.bazel", integrity = "sha256-ZCwsZ5yQF6tv3tAzJOTOm19Ckkc7YlIOgqrOu2PAziA=", strip_prefix = "tcllib-2.0", urls = ["https://core.tcl-lang.org/tcllib/uv/tcllib-2.0.tar.xz"],
) register_toolchains( "//toolchain",
) Then in //toolchain/BUILD.bazel: load("@rules_tcl//tcl:tcl_toolchain.bzl", "tcl_toolchain") tcl_toolchain( name = "tcl_toolchain", tclsh = "@tcl_lang//:tclsh", tclcore = "@tcl_lang//:tcl_core", tcllib = "@tcllib", wrapper_template = "@rules_tcl//tcl/private:binary_wrapper.tpl", wrapper_entrypoint = "@rules_tcl//tcl/private:entrypoint.tcl",
) toolchain( name = "toolchain", toolchain = ":tcl_toolchain", toolchain_type = "@rules_tcl//tcl:toolchain_type",
) See the examples/ directory for a working setup. Users who need a custom interpreter (e.g. a vendor tool's tclsh) or a custom wrapper stub swap the corresponding attribute — see the tcl_toolchain rule doc for the full contract.

